type Flag is Data:
  Up{}
  Down{}

type Foo is Data:
  True{+value: Flag}
  False{+value: Flag}
  Zero{+value: Flag}
  Succ{+value: Flag}
  SNil{+value: Flag}
  SCon{+value: Flag}
  Chr{+value: Flag}
  Tuple{+value: Flag}
  ALeaf{+value: Flag}
  ANode{+value: Flag}

def pick(f: Foo) -> Flag:
  match f:
    case True{value}: value
    case False{value}: value
    case Zero{value}: value
    case Succ{value}: value
    case SNil{value}: value
    case SCon{value}: value
    case Chr{value}: value
    case Tuple{value}: value
    case ALeaf{value}: value
    case ANode{value}: value

def make0() -> Foo:
  True{Up{}}

def make1() -> Foo:
  False{Up{}}

def make2() -> Foo:
  Zero{Up{}}

def make3() -> Foo:
  Succ{Up{}}

def make4() -> Foo:
  SNil{Up{}}

def make5() -> Foo:
  SCon{Up{}}

def make6() -> Foo:
  Chr{Up{}}

def make7() -> Foo:
  Tuple{Up{}}

def make8() -> Foo:
  ALeaf{Up{}}

def make9() -> Foo:
  ANode{Up{}}
